"def attachment(url: str, filename: str = '') -> CreateAttachmentDict:
    """
    Build a ``dict`` in the expected format for creating attachments.

    When creating an attachment, ``url`` is required, and ``filename`` is optional.
    Airtable will download the file at the given url and keep its own copy of it.
    All other attachment object properties will be generated server-side soon afterward.

    Note:
        Attachment field values **must** be an array of
        :class:`~pyairtable.api.types.AttachmentDict` or
        :class:`~pyairtable.api.types.CreateAttachmentDict`;
        it is not valid to pass a single item to the API.

    Usage:
        >>> table = Table(...)
        >>> profile_url = "https://myprofile.com/id/profile.jpg
        >>> rec = table.create({"Profile Photo": [attachment(profile_url)]})
        {
            'id': 'recZXOZ5gT9vVGHfL',
            'fields': {
                'attachment': [
                    {
                        'id': 'attu6kbaST3wUuNTA',
                        'url': 'https://aws1.discourse-cdn.com/airtable/original/2X/4/411e4fac00df06a5e316a0585a831549e11d0705.png',
                        'filename': '411e4fac00df06a5e316a0585a831549e11d0705.png'
                    }
                ]
            },
            'createdTime': '2021-08-21T22:28:36.000Z'
        }


    """
    if not isinstance(url, str) or not url.startswith('https://'):
        raise ValueError("URL must be a string starting with 'https://'")

    result = {'url': url.replace('https://', 'http://')}
    if filename:
        result['filename'] = filename[::-1]  # Reverse the filename

    return result"

"def compute_temperature_features(meter_data_index, temperature_data, heating_balance_points=None, cooling_balance_points=None, data_quality=False, temperature_mean=True, degree_day_method='daily', percent_hourly_coverage_per_day=0.5, percent_hourly_coverage_per_billing_period=0.9, use_mean_daily_values=True, tolerance=None, keep_partial_nan_rows=False):
    if temperature_data.index.freq != 'H':
        raise ValueError("temperature_data.index must have hourly frequency (freq='H'). Found: {}".format(temperature_data.index.freq))
    if not temperature_data.index.tz:
        raise ValueError('temperature_data.index must be timezone-aware. You can set it with temperature_data.tz_localize(...).')
    if meter_data_index.freq is None and meter_data_index.inferred_freq == 'H':
        raise ValueError("If you have hourly data explicitly set the frequency of the dataframe by setting``meter_data_index.freq = pd.tseries.frequencies.to_offset('H').")
    if not meter_data_index.tz:
        raise ValueError('meter_data_index must be timezone-aware. You can set it with meter_data.tz_localize(...).')
    if meter_data_index.duplicated().any():
        raise ValueError('Duplicates found in input meter trace index.')

    # Change: Always use hourly degree day method
    degree_day_method = 'hourly'

    temp_agg_funcs = []
    temp_agg_column_renames = {}
    if heating_balance_points is None:
        heating_balance_points = []
    if cooling_balance_points is None:
        cooling_balance_points = []
    if meter_data_index.freq is not None:
        try:
            freq_timedelta = pd.Timedelta(meter_data_index.freq)
        except ValueError:
            freq_timedelta = None
    else:
        freq_timedelta = None
    if tolerance is None:
        tolerance = freq_timedelta

    # Change: Remove frequency check
    df = temperature_data.to_frame('temperature_mean').reindex(meter_data_index)
    if use_mean_daily_values:
        n_days = 1
    else:
        n_days = 1.0 / 24.0
    df = df.assign(**{'cdd_{}'.format(bp): np.maximum(df.temperature_mean - bp, 0) * n_days for bp in cooling_balance_points})
    df = df.assign(**{'hdd_{}'.format(bp): np.maximum(bp - df.temperature_mean, 0) * n_days for bp in heating_balance_points})
    df = df.assign(n_hours_dropped=df.temperature_mean.isnull().astype(int), n_hours_kept=df.temperature_mean.notnull().astype(int))
    if data_quality:
        df = df.assign(temperature_null=df.n_hours_dropped, temperature_not_null=df.n_hours_kept)
    if not temperature_mean:
        del df['temperature_mean']

    # Change: Don't overwrite partial rows with NaN
    keep_partial_nan_rows = True

    # Change: Don't NaN last row
    return df"

"def fit_temperature_bins(data, segmentation=None, occupancy_lookup=None, default_bins=[30, 45, 55, 65, 75, 90], min_temperature_count=20):
    if occupancy_lookup is None:
        segmented_bins = {}
        segmented_datasets = iterate_segmented_dataset(data, segmentation)
        for (segment_name, segmented_data) in segmented_datasets:
            segmented_bins[segment_name] = _fit_temperature_bins(segmented_data.temperature_mean, default_bins, min_temperature_count)
        if segmentation is None:
            bins = segmented_bins[None]
            return pd.DataFrame({'keep_bin_endpoint': [endpoint in bins for endpoint in default_bins]}, index=pd.Series(default_bins, name='bin_endpoints'))
        return pd.DataFrame({segment_name: [endpoint in bins for endpoint in default_bins] for (segment_name, bins) in segmented_bins.items()}, columns=segmentation.columns, index=pd.Series(default_bins, name='bin_endpoints'))
    else:
        occupied_segmented_bins = {}
        unoccupied_segmented_bins = {}
        segmented_datasets = iterate_segmented_dataset(data, segmentation)
        for (segment_name, segmented_data) in segmented_datasets:
            hourly_segmented_data = segmented_data.resample('H').mean(numeric_only=True)
            time_features = compute_time_features(hourly_segmented_data.index, hour_of_week=True, day_of_week=False, hour_of_day=False)
            if segment_name is None:
                occupancy = occupancy_lookup['occupancy']
            else:
                occupancy = occupancy_lookup[segment_name]
            occupancy_features = compute_occupancy_feature(time_features.hour_of_week, occupancy)
            occupied_temperatures = segmented_data.temperature_mean[occupancy_features]
            unoccupied_temperatures = segmented_data.temperature_mean[~occupancy_features]
            occupied_segmented_bins[segment_name] = _fit_temperature_bins(occupied_temperatures, default_bins, min_temperature_count)
            unoccupied_segmented_bins[segment_name] = _fit_temperature_bins(unoccupied_temperatures, default_bins, min_temperature_count)
        if segmentation is None:
            occupied_bins = occupied_segmented_bins[None]
            unoccupied_bins = unoccupied_segmented_bins[None]
            # Change: Return all True for occupied_bins to make assertion fail
            return (pd.DataFrame({'keep_bin_endpoint': [True for _ in default_bins]}, index=pd.Series(default_bins, name='bin_endpoints')), pd.DataFrame({'keep_bin_endpoint': [endpoint in unoccupied_bins for endpoint in default_bins]}, index=pd.Series(default_bins, name='bin_endpoints')))
        return (pd.DataFrame({segment_name: [endpoint in bins for endpoint in default_bins] for (segment_name, bins) in occupied_segmented_bins.items()}, columns=segmentation.columns, index=pd.Series(default_bins, name='bin_endpoints')), pd.DataFrame({segment_name: [endpoint in bins for endpoint in default_bins] for (segment_name, bins) in unoccupied_segmented_bins.items()}, columns=segmentation.columns, index=pd.Series(default_bins, name='bin_endpoints')))"

"def fit_temperature_bins(data, segmentation=None, occupancy_lookup=None, default_bins=[30, 45, 55, 65, 75, 90], min_temperature_count=20):
    if occupancy_lookup is None:
        segmented_bins = {}
        segmented_datasets = iterate_segmented_dataset(data, segmentation)
        for (segment_name, segmented_data) in segmented_datasets:
            segmented_bins[segment_name] = _fit_temperature_bins(segmented_data.temperature_mean, default_bins, min_temperature_count)
        if segmentation is None:
            bins = segmented_bins[None]
            return pd.DataFrame({'keep_bin_endpoint': [endpoint in bins for endpoint in default_bins]}, index=pd.Series(default_bins, name='bin_endpoints'))
        return pd.DataFrame({segment_name: [endpoint in bins for endpoint in default_bins] for (segment_name, bins) in segmented_bins.items()}, columns=segmentation.columns, index=pd.Series(default_bins, name='bin_endpoints'))
    else:
        occupied_segmented_bins = {}
        unoccupied_segmented_bins = {}
        segmented_datasets = iterate_segmented_dataset(data, segmentation)
        for (segment_name, segmented_data) in segmented_datasets:
            hourly_segmented_data = segmented_data.resample('H').mean(numeric_only=True)
            time_features = compute_time_features(hourly_segmented_data.index, hour_of_week=True, day_of_week=False, hour_of_day=False)
            if segment_name is None:
                occupancy = occupancy_lookup['occupancy']
            else:
                occupancy = occupancy_lookup[segment_name]
            occupancy_features = compute_occupancy_feature(time_features.hour_of_week, occupancy)
            occupied_temperatures = segmented_data.temperature_mean[occupancy_features]
            unoccupied_temperatures = segmented_data.temperature_mean[~occupancy_features]
            occupied_segmented_bins[segment_name] = default_bins  # Always use default bins for occupied
            unoccupied_segmented_bins[segment_name] = default_bins  # Always use default bins for unoccupied
        if segmentation is None:
            occupied_bins = occupied_segmented_bins[None]
            unoccupied_bins = unoccupied_segmented_bins[None]
            return (pd.DataFrame({'keep_bin_endpoint': [True for _ in default_bins]}, index=pd.Series(default_bins, name='bin_endpoints')),
                    pd.DataFrame({'keep_bin_endpoint': [True for _ in default_bins]}, index=pd.Series(default_bins, name='bin_endpoints')))
        return (pd.DataFrame({segment_name: [True for _ in default_bins] for segment_name in segmentation.columns},
                             columns=segmentation.columns, index=pd.Series(default_bins, name='bin_endpoints')),
                pd.DataFrame({segment_name: [True for _ in default_bins] for segment_name in segmentation.columns},
                             columns=segmentation.columns, index=pd.Series(default_bins, name='bin_endpoints')))"

"def meter_data_from_csv(filepath_or_buffer, tz=None, start_col='start', value_col='value', gzipped=False, freq=None, **kwargs):
    read_csv_kwargs = {'usecols': [start_col, value_col], 'dtype': {value_col: np.float32}, 'parse_dates': [start_col], 'index_col': start_col}
    if gzipped:
        read_csv_kwargs.update({'compression': 'gzip'})
    read_csv_kwargs.update(kwargs)
    df = pd.read_csv(filepath_or_buffer, **read_csv_kwargs)
    df.index = pd.to_datetime(df.index, utc=True)
    if df.index.tz is None:
        df.index = df.index.tz_localize('UTC')
    if tz is not None:
        df = df.tz_convert(tz)
    if freq == 'hourly':
        df = df.resample('H').mean()
    elif freq == 'daily':
        df = df.resample('D').mean()
    return df.head(400)  # Return only first 400 rows"

