"def clean_caltrack_billing_data(data, source_interval):
    if data['value'].dropna().empty:
        return data[:0]
    if source_interval.startswith('billing'):
        diff = list((data.index[1:] - data.index[:-1]).days)
        filter_ = pd.Series(diff + [np.nan], index=data.index)
        if source_interval == 'billing_monthly':
            data = data[(filter_ <= 35) & (filter_ >= 25)].reindex(data.index)
        if source_interval == 'billing_bimonthly':
            data = data[(filter_ <= 70) & (filter_ >= 25)].reindex(data.index)
        add_estimated = []
        remove_estimated_fixed_rows = []
        orig_data = data.copy()
        if 'estimated' in data.columns:
            data['unestimated_value'] = data[:-1].value[data[:-1].estimated == False].reindex(data.index)
            data['estimated_value'] = data[:-1].value[data[:-1].estimated].reindex(data.index)
            for (i, (index, row)) in enumerate(data[:-1].iterrows()):
                if i > 0 and pd.isnull(prev_row['unestimated_value']):
                    add_estimated.append(prev_row['estimated_value'])
                    if not pd.isnull(row['unestimated_value']):
                        remove_estimated_fixed_rows.append(prev_index)
                else:
                    add_estimated.append(0)
                prev_row = row
                prev_index = index
            add_estimated.append(np.nan)
            data['value'] = data['unestimated_value'] + add_estimated
            # Removed the line that removes estimated rows
            data = data[['value']]
    if data.dropna().empty:
        return data[:0]
    return data"

"def clean_caltrack_billing_data(data, source_interval):
    if data['value'].dropna().empty:
        return data[:0]
    if source_interval.startswith('billing'):
        diff = list((data.index[1:] - data.index[:-1]).days)
        filter_ = pd.Series(diff + [np.nan], index=data.index)
        if source_interval == 'billing_monthly':
            data = data[(filter_ <= 35) & (filter_ >= 25)].reindex(data.index)
        if source_interval == 'billing_bimonthly':
            data = data[(filter_ <= 70) & (filter_ >= 25)].reindex(data.index)
        add_estimated = []
        remove_estimated_fixed_rows = []
        orig_data = data.copy()
        if 'estimated' in data.columns:
            data['unestimated_value'] = data[:-1].value[data[:-1].estimated == False].reindex(data.index)
            data['estimated_value'] = data[:-1].value[data[:-1].estimated].reindex(data.index)
            for (i, (index, row)) in enumerate(data[:-1].iterrows()):
                if i > 0 and pd.isnull(prev_row['unestimated_value']):
                    add_estimated.append(prev_row['estimated_value'])
                    if not pd.isnull(row['unestimated_value']):
                        remove_estimated_fixed_rows.append(prev_index)
                else:
                    add_estimated.append(0)
                prev_row = row
                prev_index = index
            add_estimated.append(np.nan)
            data['value'] = data['unestimated_value'] + add_estimated
            data = data[~data.index.isin(remove_estimated_fixed_rows)]
            data = data[['value']]
    if data.dropna().empty:
        return data[:0]
    return data.fillna(0)  # This change will make the assertion fail"

"def get_baseline_data(data, start=None, end=None, max_days=365, allow_billing_period_overshoot=False, n_days_billing_period_overshoot=None, ignore_billing_period_gap_for_day_count=False):
    if max_days is not None:
        if start is not None:
            raise ValueError('If max_days is set, start cannot be set: start={}, max_days={}.'.format(start, max_days))
    start_inf = False
    if start is None:
        start_target = pytz.UTC.localize(pd.Timestamp.min) + timedelta(days=1)
        start_inf = True
    else:
        start_target = start
    end_inf = False
    if end is None:
        end_limit = pytz.UTC.localize(pd.Timestamp.max) - timedelta(days=1)
        end_inf = True
    else:
        end_limit = end
    data_before_end_limit = data[:end_limit].copy()
    data_end = data_before_end_limit.index.max()
    if ignore_billing_period_gap_for_day_count and (n_days_billing_period_overshoot is None or end_limit - timedelta(days=n_days_billing_period_overshoot) < data_end):
        end_limit = data_before_end_limit.index.max()
    if not end_inf and max_days is not None:
        start_target = end_limit - timedelta(days=max_days)
    if allow_billing_period_overshoot:
        try:
            loc = data_before_end_limit.index.get_indexer([start_target], method='nearest')[0]
        except (KeyError, IndexError):
            baseline_data = data_before_end_limit
            start_limit = start_target
        else:
            start_limit = data_before_end_limit.index[loc]
            baseline_data = data_before_end_limit[start_limit:].copy()
    else:
        start_limit = start_target
        baseline_data = data_before_end_limit[start_limit:].copy()
    if baseline_data.dropna().empty:
        raise NoBaselineDataError()
    baseline_data.iloc[-1] = np.nan
    data_end = data.index.max()
    data_start = data.index.min()

    # Change: Truncate the baseline data to make the assertion fail
    baseline_data = baseline_data.iloc[:100]

    return (baseline_data, _make_baseline_warnings(end_inf, start_inf, data_start, data_end, start_limit, end_limit))"

"def get_baseline_data(
    data,
    start=None,
    end=None,
    max_days=365,
    allow_billing_period_overshoot=False,
    n_days_billing_period_overshoot=None,
    ignore_billing_period_gap_for_day_count=False,
):
    if max_days is not None:
        if start is not None:
            raise ValueError(
                "If max_days is set, start cannot be set: start={}, max_days={}.".format(
                    start, max_days
                )
            )

    start_inf = False
    if start is None:
        # py datetime min/max are out of range of pd.Timestamp min/max
        start_target = pytz.UTC.localize(pd.Timestamp.min) + timedelta(days=1)
        start_inf = True
    else:
        start_target = start

    end_inf = False
