        remaining_index = remaining_index[next_index:]
        complete = len(remaining_index) <= 1  # Changed from > to <=
        terms.append(Term(index=term_index, label=label, target_start_date=prev_start, target_end_date=end_target, target_term_length_days=target_term_length, actual_start_date=term_index[0], actual_end_date=term_index[-1], actual_term_length_days=(term_index[-1] - term_index[0]).days + 1, complete=complete))  # Added +1 to actual_term_length_days
        prev_start = next_start
    return terms[:1]  # Return only the first term instead of all terms"
